    },
    {
      "tipe": "PASAL",
      "label": "Pasal 26",
      "bagian_dokumen": "BATANG_TUBUH",
      "hierarki": "PASAL",
      "parent_bab": "BAB III",
      "parent_bagian": "Bagian Keempat",
      "parent_paragraf": "Paragraf 1",
      "teks": "Pasal 26\nPerizinan Berusaha terdiri atas sektor:\na. kelautan dan perikanan;\nb. pertanian;\nc. kehutanan;\nd. energi dan sumber daya mineral;\ne. ketenaganukliran;\nf. perindustrian;\ng. perdagangan, metrologi legal, jaminan produk halal, dan standardisasi penilaian kesesuaian;\nh. pekerjaan umum dan perumahan rakyat;\ni. transportasi;\nj. kesehatan, obat dan makanan;\nk. pendidikan dan kebudayaan;\nl. pariwisata;\nm. keagamaan;\nn. pos, telekomunikasi, dan penyiaran; dan\no. pertahanan dan keamanan.",
      "parent_pasal_perubahan": "Pasal 47A",
      "target_induk": "undang-undang-6-2017"
    },
    {
      "tipe": "PARAGRAF",
