    {
      "tipe": "PASAL_PERUBAHAN",
      "label": "Pasal 112",
      "bagian_dokumen": "BATANG_TUBUH",
      "hierarki": "PASAL_PERUBAHAN",
      "parent_bab": "BAB III",
      "parent_bagian": "Bagian Keempat",
      "parent_paragraf": "Paragraf 9",
      "parent_pasal_perubahan": "Pasal 51",
      "teks": "21. Pasal 112 dihapus.",
